<template>
    <el-dialog v-model="pointEditorVisible" :title="pointForm.id?'编辑器材':'录入器材'" class="fire-dialog" width="min(680px,95vw)" align-center :close-on-click-modal="false">
      <el-form label-position="top" :disabled="managing">
        <div class="fire-form-grid"><el-form-item v-if="areas.length>1" label="所属区域"><el-select v-model="pointForm.areaId" placeholder="请选择区域"><el-option v-for="area in areas" :key="area.id" :label="area.name" :value="area.id" /></el-select></el-form-item><el-form-item label="所属工段"><el-select v-model="pointForm.sectionName" filterable allow-create clearable placeholder="请选择或输入工段"><el-option v-for="section in sections" :key="section" :label="section" :value="section" /></el-select></el-form-item><el-form-item label="具体位置" required><el-input v-model="pointForm.location" maxlength="300" placeholder="例如：三车间三楼东侧门口" /></el-form-item></div>
        <div v-for="(asset,index) in pointForm.assets" :key="asset.localKey" class="editor-asset">
          <div class="fire-form-grid"><el-form-item label="器材类型" required><el-select v-model="asset.type"><el-option label="灭火器" value="extinguisher" /><el-option label="消防栓" value="hydrant" /></el-select></el-form-item><el-form-item label="器材编码" required><el-input v-model="asset.code" maxlength="100" placeholder="与现场检查卡一致" /></el-form-item></div>
          <details><summary>其他资料</summary><div class="fire-form-grid"><el-form-item label="规格"><el-input v-model="asset.spec" maxlength="160" /></el-form-item><el-form-item label="生产厂家"><el-input v-model="asset.manufacturer" maxlength="180" /></el-form-item><el-form-item label="出厂日期"><el-input v-model="asset.manufacturedDate" maxlength="80" /></el-form-item><el-form-item label="使用状态"><el-select v-model="asset.status"><el-option label="在用" value="active" /><el-option label="未配置" value="unconfigured" /><el-option label="维修中" value="repair" /><el-option label="退役" value="retired" /></el-select></el-form-item></div><el-input v-model="asset.notes" placeholder="备注" maxlength="1000" /></details>
          <el-button v-if="pointForm.assets.length>1" text type="danger" @click="pointForm.assets.splice(index,1)">移除此器材</el-button>
        </div>
        <el-button text type="primary" @click="addAsset">添加同位置器材</el-button>
      </el-form><el-alert v-if="manageError" :title="manageError" type="error" :closable="false" /><template #footer><el-button :disabled="managing" @click="pointEditorVisible=false">取消</el-button><el-button type="primary" :loading="managing" @click="savePoint">保存器材</el-button></template>
    </el-dialog>

    <el-dialog v-model="settingsVisible" title="消防点检设置" class="fire-dialog fire-settings-dialog" width="min(880px,94vw)" align-center append-to-body :close-on-click-modal="false" :close-on-press-escape="!managing" :show-close="!managing"><el-tabs><el-tab-pane label="区域"><div class="inline-field"><el-input v-model="areaName" placeholder="新增区域名称" maxlength="100" /><el-button type="primary" :loading="managing" @click="createArea">新增</el-button></div><div class="setting-areas"><div v-for="area in areas" :key="area.id" class="setting-area">{{ area.name }}</div></div></el-tab-pane><el-tab-pane label="其他人员区域授权"><p class="fire-note">原粮人员按账号岗位自动获得消防权限；此处仅设置其他人员的区域。</p><el-select v-model="memberUserId" placeholder="选择人员" filterable @change="selectMember"><el-option v-for="user in users.filter(u=>u.enabled!==false&&!['admin','raw_grain'].includes(u.role)&&!(u.role==='viewer'&&u.staffWorkshopCode==='raw_grain'))" :key="user.id" :label="user.displayName || user.username" :value="user.id" /></el-select><el-checkbox-group v-model="memberAreaIds" class="area-checkboxes"><el-checkbox v-for="area in areas" :key="area.id" :label="area.name" :value="area.id" /></el-checkbox-group><el-button type="primary" :disabled="!memberUserId" :loading="managing" @click="saveMember">保存授权</el-button><p class="fire-note">取消全部区域后，此人员将失去消防点检访问权限；系统管理员保留管理权限。</p></el-tab-pane></el-tabs><el-alert v-if="manageError" :title="manageError" type="error" :closable="false" /><template #footer><el-button :disabled="managing" @click="settingsVisible=false">关闭</el-button></template></el-dialog>


    <el-dialog v-model="importVisible" title="导入消防台账" class="fire-dialog" width="min(1040px,96vw)" align-center :close-on-click-modal="false"><p class="fire-note">选择需要导入的记录；已导入行不会重复创建。</p><template v-if="!importPreview"><input type="file" accept=".xlsx" :disabled="importBusy" @change="chooseImport" /><el-button :disabled="!importFile" :loading="importBusy" @click="previewImport">校验文件</el-button></template><el-alert v-if="importError" :title="importError" type="error" :closable="false" /><div v-if="importPreview" class="import-preview"><p><strong>{{ importRows.length }} 行</strong> · {{ importPreview.counts?.warningCount || 0 }} 项警告</p><h4>导入记录预览</h4><p class="fire-note">已选 {{ selectedSourceKeys.length }} 行。重复编号默认不选，未选记录可稍后继续核对。</p><el-table :data="displayedImportRows" max-height="340" border row-key="sourceKey"><el-table-column label="导入" width="65" fixed="left"><template #header><el-checkbox :model-value="allImportSelected" :indeterminate="selectedSourceKeys.length>0&&!allImportSelected" aria-label="全选导入记录" @change="toggleAllImport" /></template><template #default="{row}"><el-checkbox :model-value="selectedSourceKeys.includes(row.sourceKey)" :disabled="row.alreadyImported" :title="row.alreadyImported?'已导入，不重复创建':'选择此行'" :aria-label="`导入 ${row.sheet} 第${row.row}行`" @change="toggleImport(row.sourceKey)" /></template></el-table-column><el-table-column prop="sheet" label="工作表" min-width="110" /><el-table-column prop="row" label="行" width="65" /><el-table-column prop="sectionName" label="工段" min-width="110" /><el-table-column prop="area" label="区域" min-width="100" /><el-table-column prop="location" label="位置" min-width="160" /><el-table-column prop="code" label="器材编号" min-width="110" /><el-table-column label="类型" width="90"><template #default="{row}">{{ typeName(row.type) }}</template></el-table-column><el-table-column prop="quantity" label="数量" width="80" /><el-table-column prop="notes" label="备注" min-width="140" /><el-table-column label="待核实内容" min-width="260"><template #default="{row}">{{ (row.warnings||[]).join('；') }}</template></el-table-column></el-table><div v-if="importRows.length>50" class="pagination-bar"><el-pagination v-model:current-page="importPage" :page-size="50" :total="importRows.length" layout="total, prev, pager, next" :pager-count="5" /></div><el-checkbox v-if="selectedImportWarnings.length" v-model="acknowledgeWarnings" class="import-ack">我已核对所选记录的警告</el-checkbox></div><template #footer><el-button :disabled="importBusy" @click="importVisible=false">取消</el-button><el-button type="primary" :loading="importBusy" :disabled="!importPreview || !selectedSourceKeys.length || (selectedImportWarnings.length && !acknowledgeWarnings)" @click="commitImport">确认导入</el-button></template></el-dialog>


</template>

<script setup>
import { inject, toRefs } from 'vue'

const { sections, areas, users, points, loading, settingsVisible, managing, manageError, areaName, memberUserId, memberAreaIds, pointEditorVisible, pointForm, importVisible, importBusy, importFile, importPreview, selectedImportWarnings, importError, acknowledgeWarnings, selectedSourceKeys, importRows, importPage, displayedImportRows, allImportSelected, typeName, location, addAsset, savePoint, createArea, selectMember, saveMember, chooseImport, toggleImport, toggleAllImport, previewImport, commitImport } = toRefs(inject('fireInspection'))
</script>
